import { InvalidStateTransitionError, ValidationError } from './errors';
import { OrderLine } from './OrderLine';
import { OrderStatus, isCancellable, nextStatus } from './OrderStatus';
import { Quantity } from './Quantity';

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly lines: ReadonlyArray<{ readonly productId: string; readonly quantity: number }>;
  readonly status: OrderStatus;
  readonly placedAt: Date;
  readonly updatedAt: Date;
}

export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    private currentStatus: OrderStatus,
    readonly placedAt: Date,
    private lastUpdatedAt: Date,
  ) {}

  /** Creates a placed order, merging duplicate product lines. */
  static place(id: string, customerId: string, lines: readonly OrderLine[], now: Date): Order {
    if (customerId.trim() === '') throw new ValidationError('Customer id must not be empty');
    if (lines.length === 0) throw new ValidationError('An order must contain at least one line');

    const merged = new Map<string, Quantity>();
    for (const line of lines) {
      const existing = merged.get(line.productId);
      merged.set(line.productId, existing ? existing.add(line.quantity) : line.quantity);
    }
    const mergedLines = [...merged].map(([productId, quantity]) => ({ productId, quantity }));
    return new Order(id, customerId, mergedLines, 'placed', now, now);
  }

  static restore(snapshot: OrderSnapshot): Order {
    return new Order(
      snapshot.id,
      snapshot.customerId,
      snapshot.lines.map((l) => ({ productId: l.productId, quantity: Quantity.of(l.quantity) })),
      snapshot.status,
      new Date(snapshot.placedAt),
      new Date(snapshot.updatedAt),
    );
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  get updatedAt(): Date {
    return this.lastUpdatedAt;
  }

  /** Moves to `target`, which must be the immediate next fulfilment state. */
  advanceTo(target: OrderStatus, now: Date): void {
    if (nextStatus(this.currentStatus) !== target) {
      throw new InvalidStateTransitionError(this.currentStatus, target);
    }
    this.currentStatus = target;
    this.lastUpdatedAt = now;
  }

  cancel(now: Date): void {
    if (!isCancellable(this.currentStatus)) {
      throw new InvalidStateTransitionError(this.currentStatus, 'cancelled');
    }
    this.currentStatus = 'cancelled';
    this.lastUpdatedAt = now;
  }

  toSnapshot(): OrderSnapshot {
    return {
      id: this.id,
      customerId: this.customerId,
      lines: this.lines.map((l) => ({ productId: l.productId, quantity: l.quantity.value })),
      status: this.currentStatus,
      placedAt: new Date(this.placedAt),
      updatedAt: new Date(this.lastUpdatedAt),
    };
  }
}

