export const ORDER_STATUSES = [
  'placed',
  'paid',
  'packed',
  'shipped',
  'delivered',
  'cancelled',
] as const;

export type OrderStatus = (typeof ORDER_STATUSES)[number];

/** The forward-only fulfilment sequence. */
const FULFILMENT_SEQUENCE: readonly OrderStatus[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

const CANCELLABLE: ReadonlySet<OrderStatus> = new Set<OrderStatus>(['placed', 'paid', 'packed']);

export function isOrderStatus(value: unknown): value is OrderStatus {
  return typeof value === 'string' && (ORDER_STATUSES as readonly string[]).includes(value);
}

/** The status that directly follows `status`, or undefined if it is terminal. */
export function nextStatus(status: OrderStatus): OrderStatus | undefined {
  const index = FULFILMENT_SEQUENCE.indexOf(status);
  return index >= 0 ? FULFILMENT_SEQUENCE[index + 1] : undefined;
}

export function isCancellable(status: OrderStatus): boolean {
  return CANCELLABLE.has(status);
}

