import { InsufficientStockError, ValidationError } from './errors';
import { Quantity } from './Quantity';

export interface ProductSnapshot {
  readonly id: string;
  readonly name: string;
  readonly onHand: number;
  readonly reserved: number;
}

/**
 * A catalogue product and its stock. `onHand` is physically in the warehouse;
 * `reserved` is the part of it promised to orders that have not shipped yet.
 */
export class Product {
  private constructor(
    readonly id: string,
    readonly name: string,
    private onHand: number,
    private reserved: number,
  ) {}

  static create(id: string, name: string, initialStock: number): Product {
    if (id.trim() === '') throw new ValidationError('Product id must not be empty');
    if (!Number.isSafeInteger(initialStock) || initialStock < 0) {
      throw new ValidationError('Initial stock must be a non-negative integer');
    }
    return new Product(id, name, initialStock, 0);
  }

  static restore(snapshot: ProductSnapshot): Product {
    return new Product(snapshot.id, snapshot.name, snapshot.onHand, snapshot.reserved);
  }

  get available(): number {
    return this.onHand - this.reserved;
  }

  canReserve(quantity: Quantity): boolean {
    return quantity.value <= this.available;
  }

  reserve(quantity: Quantity): void {
    if (!this.canReserve(quantity)) {
      throw new InsufficientStockError(this.id, quantity.value, this.available);
    }
    this.reserved += quantity.value;
  }

  release(quantity: Quantity): void {
    this.reserved = Math.max(0, this.reserved - quantity.value);
  }

  /** Reserved units leave the warehouse when the order ships. */
  dispatch(quantity: Quantity): void {
    this.reserved = Math.max(0, this.reserved - quantity.value);
    this.onHand = Math.max(0, this.onHand - quantity.value);
  }

  toSnapshot(): ProductSnapshot {
    return { id: this.id, name: this.name, onHand: this.onHand, reserved: this.reserved };
  }
}

