import { InsufficientStockError, NotFoundError } from './errors';
import { OrderLine } from './OrderLine';
import { Product } from './Product';
import { ProductRepository } from './ProductRepository';

/**
 * Applies stock movements for whole orders. Reservation is all-or-nothing:
 * every line is checked before any product is changed.
 */
export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  reserve(lines: readonly OrderLine[]): void {
    const loaded = lines.map((line) => ({ line, product: this.load(line.productId) }));
    for (const { line, product } of loaded) {
      if (!product.canReserve(line.quantity)) {
        throw new InsufficientStockError(product.id, line.quantity.value, product.available);
      }
    }
    for (const { line, product } of loaded) {
      product.reserve(line.quantity);
      this.products.save(product);
    }
  }

  release(lines: readonly OrderLine[]): void {
    for (const line of lines) {
      const product = this.load(line.productId);
      product.release(line.quantity);
      this.products.save(product);
    }
  }

  dispatch(lines: readonly OrderLine[]): void {
    for (const line of lines) {
      const product = this.load(line.productId);
      product.dispatch(line.quantity);
      this.products.save(product);
    }
  }

  private load(productId: string): Product {
    const product = this.products.findById(productId);
    if (!product) throw new NotFoundError('Product', productId);
    return product;
  }
}

